-- 127: Original BrillaPrep WASSCE BrillaPrep IRS beta content blueprint beta questions, part 6.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_127_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_127_guard;
INSERT INTO _migration_127_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_irs_b001_026' AND NOT (q.topic_id IS 'topic_was_irs_6' AND q.subject_id IS 'subj_wassce_irs' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which two primary sources form the foundation of Shari’ah?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Local rumour and personal desire","B. The Qur’an and Sunnah","C. Trade records and poetry alone","D. Astronomy and architecture"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Islamic law begins with the Qur’an and authenticated Prophetic Sunnah, with disciplined methods used for matters requiring further interpretation. Therefore the correct answer is B: The Qur’an and Sunnah.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_irs_6' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_irs_b001_026' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to published WAEC Islamic Studies learning evidence; not official WAEC examination material.' AND r.source_url IS 'https://waecgh.org/home/wassce-school/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_127_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_irs_b001_027' AND NOT (q.topic_id IS 'topic_was_irs_6' AND q.subject_id IS 'subj_wassce_irs' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is ijma in Islamic legal reasoning?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A private dream treated as public law","B. Any custom even when it contradicts revelation","C. Qualified scholarly consensus on a matter","D. A commercial partnership deed"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Ijma refers to recognised consensus among qualified scholars and is treated within legal theory as a source after the foundational texts. Therefore the correct answer is C: Qualified scholarly consensus on a matter.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_irs_6' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_irs_b001_027' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to published WAEC Islamic Studies learning evidence; not official WAEC examination material.' AND r.source_url IS 'https://waecgh.org/home/wassce-school/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_127_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_irs_b001_028' AND NOT (q.topic_id IS 'topic_was_irs_6' AND q.subject_id IS 'subj_wassce_irs' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is qiyas in Islamic legal reasoning?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Replacing revelation with personal preference","B. Memorising a chapter without understanding","C. Cancelling every earlier judgment","D. Reasoning by analogy from an established ruling and its effective cause"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Qiyas applies a known rule to a new case that shares the relevant underlying cause, using disciplined rather than arbitrary comparison. Therefore the correct answer is D: Reasoning by analogy from an established ruling and its effective cause.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_irs_6' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_irs_b001_028' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to published WAEC Islamic Studies learning evidence; not official WAEC examination material.' AND r.source_url IS 'https://waecgh.org/home/wassce-school/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_127_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_irs_b001_029' AND NOT (q.topic_id IS 'topic_was_irs_6' AND q.subject_id IS 'subj_wassce_irs' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What should guide custody decisions concerning a child after family separation?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The child’s welfare within applicable Islamic and lawful responsibilities","B. Using the child to punish the other parent","C. Ignoring care, safety and development","D. Awarding custody solely by wealth"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Al-hadanah concerns care and upbringing. Responsible decisions protect the child’s welfare and rights rather than treating custody as retaliation. Therefore the correct answer is A: The child’s welfare within applicable Islamic and lawful responsibilities.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_irs_6' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_irs_b001_029' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to published WAEC Islamic Studies learning evidence; not official WAEC examination material.' AND r.source_url IS 'https://waecgh.org/home/wassce-school/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_127_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_irs_b001_030' AND NOT (q.topic_id IS 'topic_was_irs_6' AND q.subject_id IS 'subj_wassce_irs' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why is a marriage contract important in Islam?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. It removes the need for free consent","B. It establishes a lawful union with recognised mutual rights and responsibilities","C. It permits concealment of agreed obligations","D. It makes kindness between spouses optional"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Nikah is a serious covenant requiring consent and defined responsibilities, including dignity, support and fair treatment within the marriage. Therefore the correct answer is B: It establishes a lawful union with recognised mutual rights and responsibilities.' AND q.difficulty IS 'hard' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_irs_6' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_irs_b001_030' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to published WAEC Islamic Studies learning evidence; not official WAEC examination material.' AND r.source_url IS 'https://waecgh.org/home/wassce-school/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
