INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_irs_b001_028', 'topic_was_irs_6', 'subj_wassce_irs', 'exam_wassce', NULL, NULL, 'What is qiyas in Islamic legal reasoning?', 'multiple_choice', NULL, '["A. Replacing revelation with personal preference","B. Memorising a chapter without understanding","C. Cancelling every earlier judgment","D. Reasoning by analogy from an established ruling and its effective cause"]', 'D', 'Qiyas applies a known rule to a new case that shares the relevant underlying cause, using disciplined rather than arbitrary comparison. Therefore the correct answer is D: Reasoning by analogy from an established ruling and its effective cause.', 'easy', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_irs_6', 'Identify', 'AO1', NULL, NULL, 'board_waec');
